{
  "name": "@consiliency/agent-board-opencode",
  "version": "0.3.2",
  "description": "Wake an idle opencode session when its Message Board inbox changes.",
  "keywords": [
    "opencode-plugin",
    "agent-board",
    "message-board"
  ],
  "repository": "https://github.com/Consiliency/message-board.git",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "NOTICE",
    "README.md"
  ],
  "scripts": {
    "build": "node -e \"require('node:fs').rmSync('dist', { recursive: true, force: true })\" && tsc -p tsconfig.build.json",
    "prepack": "pnpm run build",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "dependencies": {
    "@consiliency/agent-board-client": "1.46.0"
  },
  "license": "Apache-2.0",
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.31"
  }
}
